import boto3

def check_text_safety(text):
    comprehend = boto3.client('comprehend')
    response = comprehend.detect_toxic_content(
        TextSegments=[
            {
                'Text': text,
                'Type': 'PLAIN_TEXT'
            }
        ]
    )
    toxic_content_detected = any(label['Name'] == 'TOXICITY' for label in response['Labels'])
    return toxic_content_detected

if __name__ == '__main__':
    user_text = input('Enter text to check: ')
    is_safe = check_text_safety(user_text)
    print(f'Text is safe: {is_safe}')

from boto3 import client

# Initialize DynamoDB client
ddb = client('dynamodb')


def put_item(table_name, item):
    return ddb.put_item(
        TableName=table_name,
        Item=item
    )


def get_item(table_name, key):
    return ddb.get_item(
        TableName=table_name,
        Key=key
    )


def normalize_item(item):
    normalized_item = {}
    for key, value in item.items():
        if 'S' in value:
            normalized_item[key] = value['S']
        elif 'N' in value:
            normalized_item[key] = int(value['N'])
        elif 'BOOL' in value:
            normalized_item[key] = value['BOOL']
    return normalized_item
